create table `users` (`id` bigint unsigned not null auto_increment primary key, `name` varchar(255) not null, `email` varchar(255) not null, `email_verified_at` timestamp null, `password` varchar(255) not null, `remember_token` varchar(100) null, `created_at` timestamp null, `updated_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_unicode_ci';

alter table `users` add unique `users_email_unique`(`email`);

create table `password_resets` (`email` varchar(255) not null, `token` varchar(255) not null, `created_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_unicode_ci';

alter table `password_resets` add index `password_resets_email_index`(`email`);

create table `personal_access_tokens` (`id` bigint unsigned not null auto_increment primary key, `tokenable_type` varchar(255) not null, `tokenable_id` bigint unsigned not null, `name` varchar(255) not null, `token` varchar(64) not null, `abilities` text null, `last_used_at` timestamp null, `created_at` timestamp null, `updated_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_unicode_ci';

alter table `personal_access_tokens` add index `personal_access_tokens_tokenable_type_tokenable_id_index`(`tokenable_type`, `tokenable_id`);

alter table `personal_access_tokens` add unique `personal_access_tokens_token_unique`(`token`);

create table `products` (`id` bigint unsigned not null auto_increment primary key, `name` varchar(255) not null, `subtitle` varchar(255) null, `category` varchar(255) null, `description` text null, `rating` decimal(3, 2) not null default '0', `reviews` int not null default '0', `price_min` decimal(10, 2) null, `price_max` decimal(10, 2) null, `features` json null, `pack_sizes` json null, `colors` json null, `gallery` json null, `main_image` varchar(255) null, `is_best_seller` tinyint(1) not null default '0', `is_in_stock` tinyint(1) not null default '1', `created_at` timestamp null, `updated_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_unicode_ci';

create table `orders` (`id` bigint unsigned not null auto_increment primary key, `customer_name` varchar(255) not null, `customer_email` varchar(255) not null, `customer_phone` varchar(255) not null, `delivery_address` text not null, `total_amount` decimal(10, 2) not null, `status` varchar(255) not null default 'Pending', `created_at` timestamp null, `updated_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_unicode_ci';

create table `order_items` (`id` bigint unsigned not null auto_increment primary key, `order_id` bigint unsigned not null, `product_name` varchar(255) not null, `pack_size` varchar(255) not null, `quantity` int not null, `unit_price` decimal(10, 2) not null, `total_price` decimal(10, 2) not null, `created_at` timestamp null, `updated_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_unicode_ci';

alter table `order_items` add constraint `order_items_order_id_foreign` foreign key (`order_id`) references `orders` (`id`) on delete cascade;

create table `blogs` (`id` bigint unsigned not null auto_increment primary key, `title` varchar(255) not null, `slug` varchar(255) not null, `content` longtext not null, `image` varchar(255) null, `status` enum('draft', 'published') not null default 'draft', `published_at` timestamp null, `created_at` timestamp null, `updated_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_unicode_ci';

alter table `blogs` add unique `blogs_slug_unique`(`slug`);

create table `categories` (`id` bigint unsigned not null auto_increment primary key, `name` varchar(255) not null, `slug` varchar(255) not null, `description` text null, `image` varchar(255) null, `icon` varchar(255) null, `is_active` tinyint(1) not null default '1', `sort_order` int not null default '0', `created_at` timestamp null, `updated_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_unicode_ci';

alter table `categories` add unique `categories_slug_unique`(`slug`);

alter table `categories` add `show_on_home` tinyint(1) not null default '0' after `is_active`;

create table `sales_representatives` (`id` bigint unsigned not null auto_increment primary key, `name` varchar(255) not null, `designation` varchar(255) null default 'Area Sales Executive', `phone` varchar(255) not null, `whatsapp` varchar(255) null, `email` varchar(255) null, `districts` json null, `image` varchar(255) null, `is_active` tinyint(1) not null default '1', `sort_order` int not null default '0', `notes` text null, `created_at` timestamp null, `updated_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_unicode_ci';

